<?php
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}require_once __DIR__.'/../config/database.php';$db=(new Database())->getConnection();if(!$db){fwrite(STDERR,"Database unavailable\n");exit(1);}try{$db->beginTransaction();$reviews=$db->exec('DELETE FROM product_reviews WHERE is_demo=1');$orders=$db->exec('DELETE FROM orders WHERE is_demo=1');$users=$db->exec("DELETE FROM users WHERE username LIKE 'demo\\_%'");$db->commit();echo "deleted reviews=$reviews orders=$orders users=$users\n";}catch(Throwable $e){if($db->inTransaction())$db->rollBack();fwrite(STDERR,$e->getMessage()."\n");exit(1);}
